"use client";
import { AdminSkeleton } from "./admin-skeleton";
import { useEffect, useState } from "react";
import { FiDownload, FiEye, FiFile, FiFileText, FiTable, FiUpload, FiX } from "react-icons/fi";
type Document={id:string;kind:string;name:string;url:string;type:string;agent:string;createdAt:string;preview:{headers?:string[];rows?:string[][];text?:string}};
const icon=(type:string)=>["XLSX","XLS","CSV"].includes(type)?<FiTable/>:<FiFileText/>;
export function DocumentsLibrary(){const[docs,setDocs]=useState<Document[]>([]),[open,setOpen]=useState<Document|null>(null),[loading,setLoading]=useState(true),[error,setError]=useState("");useEffect(()=>{fetch("/api/admin/documents",{signal:AbortSignal.timeout(15000)}).then(r=>{if(!r.ok)throw Error("Unable to load documents");return r.json();}).then(d=>setDocs(d?.documents??[])).catch(e=>setError(e.message||"Unable to load documents")).finally(()=>setLoading(false))},[]);return <><div className="admin-page-head"><div><p>DOCUMENT LIBRARY</p><h1>Documents</h1></div></div><p className="documents-intro">Your team?s lead sheets and scripts, together in one library. Manage uploads and assignments on the Scripts page.</p>{error&&<p role="alert">{error}</p>}{loading?<AdminSkeleton rows={4} label="Loading documents"/>:docs.length?<div className="documents-grid">{docs.map(d=><article className="document-card" key={d.id}><div className={`document-type type-${d.type.toLowerCase()}`}>{icon(d.type)}<span>{d.type||"FILE"}</span></div><small>{d.kind}</small><h2 data-tooltip={d.name}>{d.name}</h2><p>Assigned to <b>{d.agent}</b></p><time>{new Date(d.createdAt).toLocaleString()}</time><div><button className="admin-outline" onClick={()=>setOpen(d)}><FiEye/> Preview</button><a className="document-download" href={d.url} download={d.name}><FiDownload/> Download</a></div></article>)}</div>:<section className="admin-card documents-empty"><div className="documents-empty-icon"><FiFile/></div><span className="documents-empty-label">YOUR DOCUMENT LIBRARY</span><h2>A home for your team?s documents</h2><p>Upload lead sheets and scripts through an agent assignment. Your files will appear here, ready to preview and download.</p><a className="document-upload-link" href="/controler?tab=scripts"><FiUpload/> Upload through Scripts</a><small>Supports PDF, Word, Excel, CSV and text files</small></section>}{open&&<div className="document-modal-backdrop" onMouseDown={()=>setOpen(null)}><section className="document-modal" role="dialog" aria-modal="true" onMouseDown={e=>e.stopPropagation()}><header><div><small>{open.kind} · {open.type}</small><h2>{open.name}</h2><p>Assigned to {open.agent} · {new Date(open.createdAt).toLocaleString()}</p></div><button aria-label="Close document preview" onClick={()=>setOpen(null)}><FiX/></button></header>{open.preview.text?<pre>{open.preview.text}</pre>:<div className="document-table"><table><thead><tr>{open.preview.headers?.map(h=><th key={h}>{h}</th>)}</tr></thead><tbody>{open.preview.rows?.slice(0,20).map((r,i)=><tr key={i}>{open.preview.headers?.map((_,j)=><td key={j}>{r[j]||"—"}</td>)}</tr>)}</tbody></table></div>}<footer><a className="document-download" href={open.url} download={open.name}><FiDownload/> Download original {open.type}</a></footer></section></div>}</>}
