function repairMojibake(value: string) {
  let repaired = value;
  for (let attempt = 0; attempt < 3 && /[ÃƒÆ’Ã†â€™ÃƒÆ’Ã‚Â¢]/.test(repaired); attempt += 1) {
    const bytes = Uint8Array.from([...repaired], char => windows1252[char.codePointAt(0) ?? 0] ?? (char.codePointAt(0) ?? 63));
    const decoded = new TextDecoder().decode(bytes);
    if (decoded === repaired) break;
    repaired = decoded;
  }
  return repaired;
}

function repairRenderedText(root: Node) {
  const walker = document.createTreeWalker(root, NodeFilter.SHOW_TEXT);
  const nodes: Text[] = [];
  while (walker.nextNode()) nodes.push(walker.currentNode as Text);
  nodes.forEach(node => {
    const repaired = repairMojibake(node.nodeValue ?? "");
    if (repaired !== node.nodeValue) node.nodeValue = repaired;
  });
}

function conciseToastMessage(message: string) {
  const clean = message.replace(/\s+/g, " ").trim();
  if (clean.length <= 120) return clean;
  const shortened = clean.slice(0, 117);
  const lastSpace = shortened.lastIndexOf(" ");
  return `${shortened.slice(0, lastSpace > 80 ? lastSpace : 117)}…`;
}
