"use client";

import { ExportMenu } from "./export-menu";
import { exportAgentReport } from "@/lib/agent-report-export";
import "./dashboard-polish.css";
import { useEffect, useMemo, useState } from "react";
import { FiActivity, FiBarChart2, FiCheckCircle, FiDownload, FiPhoneCall, FiPieChart, FiRadio, FiUsers } from "react-icons/fi";

type Call = { id: string; status: string; lead_name: string; lead_number: string; summary: string; created_at: string; answered_at?: string; ended_at?: string; agent_name: string };
type Metrics = { total: number; active: number; completed: number; answered: number; recordings: number; needs_review: number; talk_seconds: number };
const blank: Metrics = { total: 0, active: 0, completed: 0, answered: 0, recordings: 0, needs_review: 0, talk_seconds: 0 };
const colors = ["#eb6216", "#27a97b", "#f2a13a", "#df6070", "#eb6216"];

function minutes(seconds: number) { const value = Math.round(seconds / 60); return value >= 60 ? `${Math.floor(value / 60)}h ${value % 60}m` : `${value}m`; }
function LineChart({ values, color = "#eb6216", label = "Daily call volume" }: { values: number[]; color?: string; label?: string }) { const max = Math.max(...values, 1), points = values.map((v, i) => `${(i / 6) * 620 + 10},${172 - (v / max) * 142}`).join(" "), id = `gradient-${label.replaceAll(" ", "-").toLowerCase()}`; return <svg className="db-chart-svg" viewBox="0 0 640 190" role="img" aria-label={label}><defs><linearGradient id={id} x1="0" x2="0" y1="0" y2="1"><stop stopColor={color} stopOpacity=".25"/><stop offset="1" stopColor={color} stopOpacity="0"/></linearGradient></defs>{[32,72,112,152].map(y => <line key={y} x1="10" x2="630" y1={y} y2={y} stroke="#f9f1ea"/>)}<polygon points={`10,172 ${points} 630,172`} fill={`url(#${id})`}/><polyline points={points} fill="none" stroke={color} strokeWidth="4" strokeLinejoin="round" strokeLinecap="round"/>{values.map((v,i)=><circle key={i} cx={(i / 6) * 620 + 10} cy={172 - (v / max) * 142} r="4" fill="#fff" stroke={color} strokeWidth="3"/>)}</svg>; }
function Donut({ values }: { values: { label: string; value: number }[] }) { const total = Math.max(values.reduce((n, x) => n + x.value, 0), 1); return <div className="db-donut-wrap"><svg viewBox="0 0 42 42" className="db-donut" role="img" aria-label="Call status distribution">{values.map((item, index) => { const dash = item.value / total * 100, node = <circle key={item.label} cx="21" cy="21" r="15.9155" fill="transparent" stroke={colors[index]} strokeWidth="6" strokeDasharray={`${dash} ${100 - dash}`} strokeDashoffset={25-values.slice(0,index).reduce((sum,v)=>sum+v.value/total*100,0)}/>; return node; })}<text x="21" y="20" textAnchor="middle" className="db-donut-number">{total}</text><text x="21" y="25" textAnchor="middle" className="db-donut-label">CALLS</text></svg><Legend values={values}/></div>; }
function Legend({ values, horizontal = false }: { values: { label: string; value: number }[]; horizontal?: boolean }) { return <div className={`db-legend ${horizontal ? "horizontal" : ""}`}>{values.map((x,i)=><span key={x.label}><i style={{ background: colors[i] }}/>{x.label}<b>{x.value}</b></span>)}</div>; }
function BarChart({ values }: { values: { label: string; value: number }[] }) { const max = Math.max(...values.map(x => x.value), 1); return <div className="db-bars">{values.map((x,i)=><div key={x.label}><b style={{ height: `${Math.max(7, x.value / max * 100)}%`, background: colors[i] }} data-tooltip={`${x.label}: ${x.value}`}/><span>{x.label.split(" ")[0]}</span><small>{x.value}</small></div>)}</div>; }
function MiniBars({ values, labels }: { values: number[]; labels: string[] }) { const max = Math.max(...values, 1); return <div className="db-mini-bars">{values.map((value, index) => <div key={`${labels[index]}-${index}`}><b style={{ height: `${Math.max(8, value / max * 100)}%`, background: colors[index % colors.length] }} data-tooltip={`${labels[index]}: ${value}`} /><span>{labels[index]}</span><small>{value}</small></div>)}</div>; }

export function DashboardAnalytics({ onAction }: { onAction: (message: string) => void }) {
  const [exporting,setExporting]=useState(false);
  const [calls, setCalls] = useState<Call[]>([]), [metrics, setMetrics] = useState<Metrics>(blank), [loading, setLoading] = useState(true);
  useEffect(() => { let current = true; fetch("/api/admin/reports", { cache: "no-store" }).then(async r => { const data = await r.json(); if (!r.ok) throw new Error(data.message); if (current) { setCalls(data.calls ?? []); setMetrics({ ...blank, ...data.metrics }); } }).catch(e => current && onAction(e instanceof Error ? e.message : "Unable to load dashboard data.")).finally(() => current && setLoading(false)); return () => { current = false; }; }, [onAction]);
  const data = useMemo(() => { const days = loading ? [] : Array.from({ length: 7 }, (_, i) => { const d = new Date(); d.setHours(0,0,0,0); d.setDate(d.getDate() - 6 + i); return d; }); const volume = days.map(d => calls.filter(c => new Date(c.created_at).toDateString() === d.toDateString()).length); const answeredVolume = days.map(d => calls.filter(c => new Date(c.created_at).toDateString() === d.toDateString() && ["ANSWERED", "COMPLETED"].includes(c.status)).length); const completedVolume = days.map(d => calls.filter(c => new Date(c.created_at).toDateString() === d.toDateString() && c.status === "COMPLETED").length); const statuses = ["COMPLETED", "ANSWERED", "RINGING", "INITIATED"].map(status => ({ label: status[0] + status.slice(1).toLowerCase(), value: calls.filter(c => c.status === status).length })); const byAgent = Object.entries(calls.reduce<Record<string, number>>((all,c) => { all[c.agent_name || "Unassigned"] = (all[c.agent_name || "Unassigned"] || 0) + 1; return all; }, {})).map(([label,value])=>({label,value})).sort((a,b)=>b.value-a.value).slice(0,5); return { days, volume, answeredVolume, completedVolume, statuses, byAgent }; }, [calls, loading]);
  const downloadReport=async(format:"csv"|"xls"|"doc"|"pdf")=>{if(exporting||loading)return;setExporting(true);try{const r=await fetch('/api/admin/reports?export=all',{cache:'no-store'});const d=await r.json();if(!r.ok)throw Error(d.message);const m={...blank,...d.metrics};const stamp=(date?:string)=>date?new Date(date).toLocaleString('en-GB',{timeZone:'Asia/Karachi'}):'';await exportAgentReport(format,[],{title:'Operations dashboard report',headings:['Lead','Phone','Agent','Status','Started (PKT)','Answered (PKT)','Ended (PKT)','Outcome','Summary','Notes'],rows:d.calls.map((c:Call&{outcome?:string;notes?:string})=>[c.lead_name||'Unnamed lead',c.lead_number,c.agent_name,c.status,stamp(c.created_at),stamp(c.answered_at),stamp(c.ended_at),c.outcome||'',c.summary||'',c.notes||'']),summary:`Total calls: ${m.total} | Live: ${m.active} | Answered: ${m.answered} | Completed: ${m.completed} | Recordings: ${m.recordings} | Needs review: ${m.needs_review} | Talk time: ${minutes(m.talk_seconds)}`});onAction(`${format.toUpperCase()} report downloaded.`);}catch(e){onAction(e instanceof Error?e.message:'Unable to export report');}finally{setExporting(false);}};
  const avg = metrics.answered ? Math.round(metrics.talk_seconds / metrics.answered) : 0, connect = metrics.total ? Math.round(metrics.answered / metrics.total * 100) : 0;
  const cards = [[<FiPhoneCall key="calls"/>, "Total calls", metrics.total, "Database total"], [<FiRadio key="live"/>, "Live calls", metrics.active, "Now in progress"], [<FiActivity key="connect"/>, "Connect rate", `${connect}%`, `${metrics.answered} answered`], [<FiUsers key="time"/>, "Average talk time", minutes(avg), "Answered calls"], [<FiPieChart key="complete"/>, "Completed", metrics.completed, `${metrics.recordings} recordings`], [<FiBarChart2 key="review"/>, "Needs review", metrics.needs_review, "Without summary"], [<FiDownload key="recordings"/>, "Recordings", metrics.recordings, "Saved call audio"], [<FiCheckCircle key="answered"/>, "Answered calls", metrics.answered, "Connected calls"]] as const;
  return <><div className="admin-page-head"><div><p>DATABASE OVERVIEW</p><h1>Operations dashboard</h1></div><div className="dashboard-export"><ExportMenu disabled={loading||exporting} onExport={format=>void downloadReport(format)}/>{exporting&&<small role="status">Preparing complete report...</small>}</div></div><div className="agent-kpis dashboard-kpis">{cards.map(([icon,label,value,hint],index)=><section className={`agent-kpi ${["purple","green","orange","blue"][index%4]}`} key={label as string}><span>{icon}</span><div><small>{label}</small><strong>{loading ? "—" : String(value)}</strong><small className="dashboard-kpi-hint">{hint}</small></div></section>)}</div><div className="dashboard-analytics-grid"><section className="admin-card dashboard-chart-card wide"><div className="card-heading"><div><h2>Daily call volume</h2><p>Last seven days from the calls database</p></div><span className="chart-chip">7 days</span></div><LineChart values={data.volume}/><div className="db-axis">{data.days.map(d=><span key={d.toISOString()}>{d.toLocaleDateString(undefined,{weekday:"short"})}</span>)}</div></section><section className="admin-card dashboard-chart-card"><div className="card-heading"><div><h2>Call outcomes</h2><p>Current status split</p></div></div><Donut values={data.statuses}/></section><section className="admin-card dashboard-chart-card"><div className="card-heading"><div><h2>Agent performance</h2><p>Calls handled by agent</p></div></div>{data.byAgent.length ? <BarChart values={data.byAgent}/> : <p className="empty-state">No call data yet.</p>}</section><section className="admin-card dashboard-chart-card"><div className="card-heading"><div><h2>Stacked call pipeline</h2><p>Live, answered and completed</p></div></div><div className="db-stacked">{data.statuses.map((x,i)=><div key={x.label} style={{ width: `${x.value / Math.max(metrics.total,1) * 100}%`, background: colors[i] }} data-tooltip={`${x.label}: ${x.value}`}/>)}</div><Legend values={data.statuses} horizontal/></section><section className="admin-card dashboard-chart-card"><div className="card-heading"><div><h2>Answered trend</h2><p>Answered and completed calls by day</p></div></div><LineChart values={data.answeredVolume}/></section><section className="admin-card dashboard-chart-card"><div className="card-heading"><div><h2>Completed trend</h2><p>Completed calls over the last seven days</p></div></div><LineChart values={data.completedVolume}/></section><section className="admin-card dashboard-chart-card"><div className="card-heading"><div><h2>Outcome comparison</h2><p>Calls grouped by current outcome</p></div></div><MiniBars values={data.statuses.map(x => x.value)} labels={data.statuses.map(x => x.label)}/></section><section className="admin-card dashboard-chart-card"><div className="card-heading"><div><h2>Call quality signals</h2><p>Answered, recorded and review queues</p></div></div><MiniBars values={[metrics.answered, metrics.recordings, metrics.needs_review]} labels={["Answered", "Recorded", "Review"]}/></section></div></>;
}
